function test_stage4a3_open_set_audit()
root=fileparts(fileparts(mfilename('fullpath')));cfg=default_config(root);sc=stage4a3_open_set_config(cfg);p0=generate_prior_constrained_candidates(sc.generator,sc.scenarios(1).asset_prior);assert(numel(p0)==7);bank=generate_stage4a3_trial_bank(cfg,sc);assert(isempty(intersect({bank(strcmp({bank.split},'calibration')).sample_id},{bank(strcmp({bank.split},'test')).sample_id})));assert(numel(unique({bank(strcmp({bank.split},'calibration')).truth_topology_id}))==7);txt=fileread(which('match_composite_topology_library_open_set'));assert(isempty(regexp(txt,'coverage_status|truth_topology_id|scenario_id','once')));f=sc.grids(1).frequency_hz(1:5);grid=topology_parameter_grid(sc.parameter_search);ni=find([grid.regularization]==0,1);small=grid([ni,1,2]);t=grid(ni);[n,cf]=topology_apply_parameters(p0(3).network,cfg,t);[m,~]=plc_measurement_bundle(sc.measurement_kind,n,t,cf);v=plc_multiview_response(f,n,m,cf);o=struct('measurement_kind',sc.measurement_kind,'tie_tolerance',sc.tie_tolerance,'feature',sc.feature,'weights',sc.weights,'batch_size',8,'thresholds',struct('residual',1e-8,'margin',1e-12));r=match_composite_topology_library_open_set(v,f,p0,small,cfg,o);assert(~isempty(r.best_topology_id)&&~strcmp(r.decision,'reject_no_feasible_candidate'));r0=match_composite_topology_library_open_set(v,f,struct([]),small,cfg,o);assert(strcmp(r0.decision,'reject_no_feasible_candidate'));fprintf('ALL STAGE-4A.3 TESTS PASSED\n');
end
